    .macro fc_fan label, k, tnot, tdefault, tfan, tonly, tnon     // a fan's whole script
\label:
    c3_talk
    h_buffer_player
    .if \tnot != -1
    h_goto_if_eq VAR_LILYCOVE_FAN_CLUB_STATE, 0, .Lfcnot\@     // specialvar... before the game is cleared
    .endif
    fc_get_bit \k, C8_A                                         // ShouldMoveLilycoveFanClubMember
    h_goto_if_eq C8_A, 1, .Lfcfan\@
    VMCall Sub_FanClub_NumMoved                                 // GetNumMovedLilycoveFanClubMembers
    h_goto_if_eq FC_T1, 7, .Lfcnon\@
    h_msgbox \tdefault
    h_release
.Lfcfan\@:
    VMCall Sub_FanClub_NumMoved
    h_goto_if_eq FC_T1, 1, .Lfconly\@
    h_msgbox \tfan
    h_release
.Lfconly\@:
    h_msgbox \tonly
    h_release
.Lfcnon\@:
    h_msgbox \tnon
    h_release
    .if \tnot != -1
.Lfcnot\@:
    h_msgbox \tnot
    h_release
    .endif
    .endm

    .macro fc_place_if_away k, idx, x, z, dir                   // MoveMemberNToFarTable when ShouldMove is 0
    fc_get_bit \k, C8_A
    WorkCmpConst C8_A, 0
    VMJumpIf CMP_NE, .Lfcpl\@
    ObjInitNPCGPos \idx, \dir, \x, 0, \z
.Lfcpl\@:
    .endm

FC_Init:                                    // ..._OnTransition
    h_goto_if_eq VAR_LILYCOVE_FAN_CLUB_STATE, 1, L_FC_FirstMeeting
    h_goto_if_ne VAR_LILYCOVE_FAN_CLUB_STATE, 2, L_FC_InitDone
    fc_place_if_away 0, 0, 8, 6, 0
    fc_place_if_away 5, 1, 9, 5, 2
    fc_place_if_away 1, 2, 4, 5, 0
    fc_place_if_away 2, 3, 8, 3, 1
    fc_place_if_away 3, 4, 6, 6, 0
    fc_place_if_away 4, 5, 6, 3, 1
    fc_place_if_away 6, 6, 4, 4, 3
    fc_place_if_away 7, 7, 9, 4, 2
    VMHalt
L_FC_FirstMeeting:                          // ..._EventScript_SetFanMemberPositionsForFirstFanMeeting
    h_setobjectxyperm 2, 4, 5, 0      // PokefanM to the far table
    h_setobjectxyperm 4, 6, 6, 0      // NinjaBoy to the far table
    h_setobjectxyperm 5, 6, 3, 1      // Boy to the far table
    h_setobjectxyperm 6, 4, 4, 3      // Woman to the far table
    h_setobjectxyperm 7, 9, 4, 2      // ExpertF to the far table
L_FC_InitDone:
    VMHalt

FC_MeetFirstFans:                           // ..._EventScript_MeetFirstFans (lockall)
    ActorsPauseAll
    h_buffer_player
    h_applymovement 1, Mv_FC_WalkInPlaceDown
    h_waitmovement
    h_msgbox_actor T_OhWowItsPlayer, 1
    h_closemessage
    h_applymovement 4, Mv_FC_LittleGirlWatchPlayer
    h_applymovement 2, Mv_FC_FanApproachPlayer
    h_waitmovement
    h_applymovement 255, Mv_FC_PlayerFaceRight
    h_waitmovement
    h_msgbox_actor T_HeardAboutYou, 2
    h_closemessage
    h_applymovement 4, Mv_FC_LittleGirlMoveCloser
    h_waitmovement
    h_applymovement 255, Mv_FC_PlayerFaceLeft
    h_waitmovement
    h_applymovement 4, Mv_FC_LittleGirlHide
    h_waitmovement
    h_setvar VAR_LILYCOVE_FAN_CLUB_STATE, 2
    h_release

    fc_fan FC_Lass, 0, T_LassNotChampion, T_LassDefault, T_LassFan, T_LassOnlyFan, T_LassNonFan
    fc_fan FC_Man, 5, T_ManNotChampion, T_ManDefault, T_ManFan, T_ManOnlyFan, T_ManNonFan
    fc_fan FC_PokefanM, 1, T_PokefanMNotChampion, T_PokefanMDefault, T_PokefanMFan, T_PokefanMOnlyFan, T_PokefanMNonFan
    fc_fan FC_LittleGirl, 2, T_LittleGirlNotChampion, T_LittleGirlDefault, T_LittleGirlFan, T_LittleGirlOnlyFan, T_LittleGirlNonFan
    fc_fan FC_NinjaBoy, 3, -1, T_NinjaBoyDefault, T_NinjaBoyFan, T_NinjaBoyOnlyFan, T_NinjaBoyNonFan
    fc_fan FC_Boy, 4, -1, T_BoyDefault, T_BoyFan, T_BoyOnlyFan, T_BoyNonFan
    fc_fan FC_Woman, 6, -1, T_WomanDefault, T_WomanFan, T_WomanOnlyFan, T_WomanNonFan
    fc_fan FC_ExpertF, 7, -1, T_ExpertFDefault, T_ExpertFFan, T_ExpertFOnlyFan, T_ExpertFNonFan

    .balign 4, 0
Mv_FC_WalkInPlaceDown:
    walk_in_place_fastest_down
    step_end
Mv_FC_PlayerFaceRight:
    walk_in_place_fastest_right
    step_end
Mv_FC_PlayerFaceLeft:
    walk_in_place_fastest_left
    step_end
Mv_FC_FanApproachPlayer:
    delay_8
    walk_in_place_fastest_down
    walk_down 3
    walk_left 2
    step_end
Mv_FC_LittleGirlWatchPlayer:
    walk_fast_left 2
    walk_fast_down 2
    walk_fast_left
    walk_fast_down
    step_end
Mv_FC_LittleGirlMoveCloser:
    walk_down
    walk_in_place_fastest_right
    step_end
Mv_FC_LittleGirlHide:
    jump_in_place_right
    walk_fast_up 2
    walk_fast_right
    walk_in_place_fastest_down
    step_end
    .balign 4, 0
